rowdata.pyStepsJavaSource:
ParameterPage params = tools.getParameterPage(); // pass thru params page
String className = params.getString("WorkObjectClass");
StringMap flow = new HashStringMap();
flow.putString("pxObjClass", "Rule-Obj-CaseType");
//flow.putString("pyClassName", myStepPage.getClassName());
flow.putString("pyClassName", className);
flow.putString("pyPurpose", "pyDefault");
tools.doAction(flow, myStepPage, params);

ClipboardPage flowListPage = tools.findPage("pyFlowList");
if (flowListPage != null)
{
   ClipboardProperty results = flowListPage.getProperty("pxResults");
   results.add(myStepPage);
}

ClipboardPage objFlowList = tools.findPage("pyFlowList");
java.util.Hashtable hashUniqueFlowTypes = new java.util.Hashtable();
java.util.Vector vRemoveProps = new java.util.Vector();

ClipboardProperty objResults = objFlowList.getProperty("pxResults");
java.util.Iterator itResults = objResults.iterator();
while (itResults.hasNext())
{
	ClipboardProperty objOneResult = (ClipboardProperty) itResults.next();
	boolean removeFromList;
	removeFromList = false;

	ClipboardPage obResultPage = objOneResult.getPageValue();

	String strFlowType = obResultPage.getString("pyFlowType");
	String strRuleSet = obResultPage.getString("pyRuleSet");
	String strRuleSetVersion = obResultPage.getString("pyRuleSetVersion");

	// A flowtype we haven't encountered yet
	if (!hashUniqueFlowTypes.containsKey(strFlowType))
	{	
		// Check to see if the user has security to execute this flow.
		// We don't want to show it if he/she doesn't.
		if (!obResultPage.getString("pyRuleAvailable").equals("Yes") || !pega_procom_flow.HasSecurity(myStepPage, strFlowType))
		{
			// Let's remember to remove this flow from the results list at the end
			vRemoveProps.addElement(objOneResult);
		}		 		        
		hashUniqueFlowTypes.put(strFlowType, objOneResult);		        
	}

	// This is a repeat flowtype; discard it
	else 
	{
		// update the vector of property pages to be removed
		vRemoveProps.addElement(objOneResult);
	}		
}


// Now go and remove all the flows that are either dups or didn't pass security
for (int nIdx = 0 ; nIdx <= vRemoveProps.size() -1 ; nIdx ++)
{
	ClipboardProperty objOneResult = (ClipboardProperty) vRemoveProps.elementAt(nIdx);
	objOneResult.removeFromClipboard();
}

// Reset the pxResultCount
objFlowList.putString("pxResultCount", objResults.size() + "");
